// Parameter (ALLY 38, Talent-Bereich): nur die Sitzung für die Datenbank (64 Hex-Zeichen, sonst leer = nicht angemeldet). Die Talent-ID kommt in der Datenbank
// ausschließlich aus der Sitzung; Parameter aus der Adresse werden nicht verwendet.
// Migration 67: to = geöffnete Freigabe (Ziffern), tp = Unterordner darin; nur für die Ordnerliste über SPEICHER 1, geprüft in der Datenbank.
const E = $input.first().json;
const P = E.parameter || {};
const tp = String(P.tp ?? '').trim();
const ordner = { id: /^[0-9]{1,12}$/.test(String(P.to || '')) ? String(P.to) : '', pfad: tp.length <= 200 && !/[\x00-\x1f\x7f]/.test(tp) ? tp.replace(/\/+$/, '') : '' };
return [{ json: { ordner, werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : ''] } }];

// Talent-Bereich (ALLY 38, BA7, Stefan 20.10.2026): Ansicht mit der Rolle Talent nach Entwurf „Talentbereich“ – Hallo, Ansprechperson, Dein Briefing, Aufgaben (inkl. Reviews
// zu Content, Entwurf als https-Link einreichen), Termine und Erinnerungen, Deine Zahlen, Meine Accounts (Verbinden, Erneuern, Trennen, Zahlen per Screenshot,
// i-Symbol je Verbindung), Kampagnen, Dateien. Kein Knopf „Chat öffnen“, nur der Chat-Anmeldename. Keine Honorare und Budgets. Handy zuerst (Abschnitte untereinander).
// Liefert nur die Seitenbeschreibung (JSON); Daten nur aus talent_ui_daten (Talent-ID aus der Sitzung).
// BA8 (Migration 63): Abschnitt „Kalender abonnieren“ (talent_kalender_abo_ui; tb_kalender_neu, tb_kalender_widerrufen), nur wenn Termine oder Aufgaben sichtbar sind.
// Migration 64: „Zahlen per Screenshot“ nur, wenn für das Talent freigegeben (zahlen_upload nicht leer).
// Migration 67: Abschnitt „Deine Ordner“ (speicher_talent_ordner_ui): freigegebene Ordner durchsehen (to, tp; Liste über SPEICHER 1) und Dateien herunterladen
// über die interne Seite „datei“ (Ally holt die Datei, kein Direktlink zum Speicherort).
// BA9 (Migration 68): Abschnitt „Ally-Chat“ (talent_chat_selbst_ui), wenn der Ally-Chat für das Talent eingeschaltet ist: Chat-Anmeldename, Anleitung für die App Element,
// Chat-Passwort selbst festlegen (tb_chat_passwort; das Passwort geht nur an ALLY 18), Kontingent des Monats ohne Beträge. Kein Knopf „Chat öffnen“.
const E = $('Start').first().json;
const DL = $('Daten laden').first().json || {};
const D = DL.d || {};
const KAB = DL.k || {};
const OT = DL.o || {};
const CS = DL.c && DL.c.ok === true && DL.c.an === true ? DL.c : null;
const lief = n => { try { return $(n).isExecuted; } catch (e) { return false; } };
const OL = lief('Ordner lesen (SPEICHER 1)') ? ($('Ordner lesen (SPEICHER 1)').first().json || null) : null;
const OPZ = (lief('Parameter') ? $('Parameter').first().json.ordner : null) || {};
const F = E.funktion || {};
const istA = x => Array.isArray(x) ? x : [];
const s = v => String(v ?? '');
if (D.ok !== true) {
  return [{ json: { inhalt: { seite: { schluessel: 'talent-bereich', art: 'funktion', titel: s(F.name || 'Dein Bereich') },
    bloecke: [{ typ: 'text', ton: 'warn', text: 'Dein Bereich konnte gerade nicht geladen werden. Bitte die Seite neu laden.' }] } } }];
}
const AP = istA(D.ansprechpersonen).map(s).filter(Boolean);
const beschreibung = (D.firma ? 'Dein Bereich bei ' + s(D.firma) + '.' : 'Dein Bereich.')
  + (AP.length ? ' ' + (AP.length === 1 ? 'Deine Ansprechperson: ' : 'Deine Ansprechpersonen: ') + AP.join(', ') : '');
const kopf = { schluessel: 'talent-bereich', art: 'funktion', titel: 'Hallo ' + s(D.name || ''), beschreibung };
const abschnitte = [], fenster = [];
const link = (art, id) => ({ seite: 'link', parameter: { art, id: String(id) } });

// ---------- Dein Briefing (und Chat-Anmeldename, ohne Knopf „Chat öffnen“) ----------
const chat = D.chat_benutzer && !CS ? [{ typ: 'paare', eintraege: [{ label: 'Chat-Anmeldename', wert: s(D.chat_benutzer) }] }] : [];
const chatInfo = 'Mit diesem Anmeldenamen meldest du dich im Chat an (App Element).';
if (D.briefing) {
  const B = D.briefing;
  abschnitte.push({ id: 'briefing', titel: 'Dein Briefing', zahl: B.am ? s(B.am) : '', offen_standard: true, info: chat.length ? chatInfo : undefined,
    inhalt: [B.text ? { typ: 'text', text: s(B.text) } : { typ: 'text', ton: 'grau', text: 'Noch kein Briefing.' }].concat(chat) });
} else if (chat.length) abschnitte.push({ id: 'chat', titel: 'Chat', offen_standard: true, info: chatInfo, inhalt: chat });

// ---------- Ally-Chat (BA9): eigenes Chat-Konto, Chat-Passwort, Kontingent – nur eigene Daten, keine Beträge ----------
if (CS) {
  const pr = s(CS.produkt || 'Ally'), ben = s(CS.chat_benutzer), bot = s(DL.cb), adresse = s(DL.ca);
  const KI = CS.ki || {};
  const kont = KI.gesperrt === true ? 'für diesen Monat aufgebraucht' : (KI.prozent !== null && KI.prozent !== undefined ? 'zu ' + Number(KI.prozent).toLocaleString('de-DE') + ' % genutzt' : 'verfügbar');
  const inhalt = [{ typ: 'paare', eintraege: [{ label: 'Chat-Anmeldename', wert: ben }, { label: 'Chat-Passwort', wert: CS.passwort_gesetzt === true ? 'festgelegt' : 'noch nicht festgelegt' },
      { label: 'Kontingent in diesem Monat', wert: kont }] },
    { typ: 'liste', eintraege: [
      { fett: '1. App Element installieren', text: 'Für iPhone, Android oder Computer (element.io).' },
      { fett: '2. Anmelden', text: (adresse ? 'Als Server ' + adresse + ' eintragen, dann ' : '') + 'mit deinem Chat-Anmeldenamen und deinem Chat-Passwort anmelden.' },
      { fett: '3. Fragen', text: 'Einen Chat mit ' + (bot ? pr + ' (' + bot + ')' : pr) + ' starten und die Frage schreiben, zum Beispiel „Was steht in meinem Briefing?“.' }] },
    { typ: 'formular', id: 'chat-passwort', aktion: 'tb_chat_passwort', titel: CS.passwort_gesetzt === true ? 'Chat-Passwort ändern' : 'Chat-Passwort festlegen', spalten: 2, knoepfe_in_reihe: true,
      frage: CS.passwort_gesetzt === true ? 'Chat-Passwort ändern? Die Anmeldung in der App Element braucht danach das neue Passwort.' : undefined,
      felder: [{ typ: 'passwort', name: 'passwort', label: 'Neues Chat-Passwort', pflicht: true, autocomplete: 'new-password', hinweis: 'Mindestens 10 Zeichen' }],
      knoepfe: [{ text: CS.passwort_gesetzt === true ? 'Chat-Passwort ändern' : 'Chat-Passwort festlegen', art: 'neben' }] }];
  abschnitte.push({ id: 'ally-chat', titel: 'Ally-Chat', zahl: CS.passwort_gesetzt === true ? 'bereit' : 'Passwort fehlt', offen_standard: CS.passwort_gesetzt !== true,
    info: pr + ' beantwortet im Chat Fragen zu deinen eigenen Daten aus diesem Bereich: Briefing, Aufgaben, Termine, Kampagnen, Zahlen und Dateien. ' + pr + ' kann nichts ändern und kennt keine Daten anderer.', inhalt });
}

// ---------- Aufgaben (inkl. Reviews zu Content) und Deliverables ----------
const entwurfFenster = (id, titel, neu) => {
  if (fenster.some(f => f.id === 'entwurf-' + id)) return;
  // Layout 6b (Plan 32c): Hinweis am i des Fenstertitels (Baustein „hinweis“, hinweiseAlsInfo); vorher info am Formular ohne Titel, nicht angezeigt
  fenster.push({ id: 'entwurf-' + id, art: 'dialog', titel: neu ? 'Entwurf neu einreichen' : 'Entwurf einreichen', untertitel: titel, inhalt: [
    { typ: 'hinweis', text: 'Lade den Entwurf bei deinem Cloud-Dienst hoch (z. B. Google Drive, Dropbox oder OneDrive) und füge hier den Link zum Teilen ein. Die Datei selbst wird hier nicht gespeichert.' },
    { typ: 'formular', id: 'entwurf-' + id, aktion: 'tb_entwurf',
    werte: { deliverable_id: String(id) },
    felder: [{ typ: 'text', name: 'link', label: 'Link zum Entwurf', platzhalter: 'https://…', pflicht: true, autocomplete: 'off', breite: 'voll' },
      { typ: 'textbereich', name: 'kommentar', label: 'Kommentar (freiwillig)', zeilen: 3, breite: 'voll' }],
    knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Einreichen' }] }] });
};
if (D.aufgaben || D.deliverables) {
  const A = istA(D.aufgaben), DL = istA(D.deliverables);
  const offen = A.filter(a => a.status === 'offen').length;
  const inhalt = [];
  inhalt.push({ typ: 'liste', leer: 'Keine Aufgaben.', eintraege: A.map(a => {
    const e = { marke: a.status !== 'offen' ? { text: 'erledigt', ton: 'ok' } : a.art === 'review' ? { text: 'Review', ton: 'warn' } : (a.wann_text ? { text: s(a.wann_text) } : null),
      fett: s(a.titel), text: [s(a.text), a.deliverable ? 'zu ' + s(a.deliverable) : '', a.status === 'offen' && a.art === 'review' && a.wann_text ? 'bis ' + s(a.wann_text) : ''].filter(Boolean).join(' · '),
      neben: s(a.kampagne || '') };
    if (a.darf_einreichen && a.deliverable_id) { e.aktion = { text: 'Neu einreichen', fenster: 'entwurf-' + a.deliverable_id, art: 'neben' }; entwurfFenster(a.deliverable_id, s(a.deliverable || a.titel), true); }
    else if (a.darf_erledigen) e.aktion = { text: 'Erledigt', aktion: 'tb_erledigt', werte: { id: String(a.id) }, art: 'neben' };
    return e; }) });
  if (DL.length) {
    inhalt.push({ typ: 'unterueberschrift', text: 'Deine Deliverables', info: 'Was du für die Kampagnen lieferst, mit Deadline. Entwürfe reichst du als Link ein; dein Manager oder deine Managerin prüft sie und gibt Rückmeldung.' });
    inhalt.push({ typ: 'liste', leer: '', eintraege: DL.map(d => {
      const v = d.letzte_version || null;
      const e = { marke: { text: s(d.deadline_text || ''), ton: d.ueberfaellig ? 'warn' : '' }, fett: s(d.name), text: [s(d.kampagne), s(d.plattform_text), s(d.status_text),
        v ? 'Version ' + v.version + ': ' + s(v.pruefung_text) : '', v && v.hinweis ? 'Hinweis: ' + s(v.hinweis) : ''].filter(Boolean).join(' · ') };
      if (d.version_id) { e.ziel = link('v', d.version_id); e.ziel_text = 'Entwurf ansehen'; }
      if (d.darf_einreichen) { e.aktion = { text: v ? 'Neu einreichen' : 'Entwurf einreichen', fenster: 'entwurf-' + d.id, art: 'neben' }; entwurfFenster(d.id, s(d.name), !!v); }
      return e; }) });
  }
  abschnitte.push({ id: 'aufgaben', titel: 'Aufgaben', zahl: offen + ' offen', offen_standard: true, inhalt });
}

// ---------- Termine und Erinnerungen ----------
if (D.termine || D.erinnerungen) {
  const T = istA(D.termine), ER = istA(D.erinnerungen);
  const eintraege = T.map(t => ({ marke: { text: s(t.wann_text) }, fett: s(t.titel), text: [s(t.text), t.ort ? 'Ort: ' + s(t.ort) : '', t.bis_text ? 'bis ' + s(t.bis_text) : ''].filter(Boolean).join(' · ') }))
    .concat(ER.map(r => Object.assign({ marke: r.status !== 'offen' ? { text: 'erledigt', ton: 'ok' } : { text: s(r.wann_text || 'Erinnerung') }, fett: 'Erinnerung: ' + s(r.titel), text: s(r.text) },
      r.darf_erledigen ? { aktion: { text: 'Erledigt', aktion: 'tb_erledigt', werte: { id: String(r.id) }, art: 'neben' } } : {})));
  abschnitte.push({ id: 'termine', titel: 'Termine und Erinnerungen', zahl: String(T.length + ER.filter(r => r.status === 'offen').length), offen_standard: true,
    inhalt: [{ typ: 'liste', leer: 'Keine Termine und Erinnerungen.', eintraege }] });
}

// ---------- Kalender abonnieren (BA8): eigene Termine, Aufgaben und Deadlines in der eigenen Kalender-App ----------
if (KAB.ok === true && KAB.sichtbar === true) {
  const A = KAB.abo || {};
  const inhalt = [];
  if (A.aktiv !== true && A.moeglich === false) inhalt.push({ typ: 'text', ton: 'grau', text: 'Das Kalender-Abo ist gerade nicht verfügbar.' });
  else if (A.aktiv !== true) inhalt.push({ typ: 'text', text: 'Mit einem Kalender-Abo erscheinen deine Termine, Aufgaben und Deadlines in deiner Kalender-App (zum Beispiel Google Kalender, Apple Kalender oder Outlook).' },
    { typ: 'aktion', text: 'Abo-Adresse erzeugen', aktion: 'tb_kalender_neu' });
  else {
    inhalt.push(A.adresse ? { typ: 'formular', id: 'kalender-abo', aktion: 'tb_kalender_neu', frage: 'Neue Abo-Adresse erzeugen? Die bisherige gilt danach nicht mehr.',
        felder: [{ typ: 'anzeige', label: 'Abo-Adresse', wert: s(A.adresse), breite: 'voll',
          info: 'In der Kalender-App „Kalender abonnieren“ bzw. „Kalender per URL hinzufügen“ wählen und die Adresse einfügen. Die Adresse ist geheim: Wer sie kennt, sieht deine Einträge. Änderungen erscheinen je nach App mit Verzögerung.' }],
        knoepfe: [{ text: 'Neue Adresse erzeugen', art: 'neben' }] }
      : { typ: 'text', ton: 'warn', text: 'Die Abo-Adresse kann gerade nicht angezeigt werden. Bitte eine neue erzeugen.' },
      { typ: 'paare', eintraege: [{ label: 'Erstellt', wert: s(A.seit || '–') }, { label: 'Zuletzt abgerufen', wert: s(A.letzter_abruf || 'noch nie') }] },
      { typ: 'aktion', text: 'Abo beenden', aktion: 'tb_kalender_widerrufen', frage: 'Kalender-Abo beenden? Die Adresse gilt danach nicht mehr.' });
  }
  abschnitte.push({ id: 'kalender', titel: 'Kalender abonnieren', zahl: A.aktiv === true ? 'aktiv' : '', offen_standard: false, inhalt });
}

// ---------- Deine Zahlen (nur eigene Accounts, ohne Vergleich mit anderen) ----------
// Migration 65 (Stefan 20.10.2026, 09:23): bestätigte Zahlen aus Screenshots zählen mit (ohne Doppelzählung mit automatisch geladenen Zahlen); auch ohne verbundenen Account
if (D.zahlen) {
  const Z = D.zahlen;
  const wert = k => s(((Z[k] || {}).text) || '–');
  const nm = Number(Z.manuell) || 0;
  abschnitte.push({ id: 'zahlen', titel: 'Deine Zahlen', zahl: 'letzte 28 Tage', offen_standard: true,
    info: 'Zahlen deiner verbundenen Accounts und bestätigte manuelle Daten, ' + s(Z.zeitraum) + '.'
      + (nm > 0 ? ' Enthalten: ' + nm + (nm === 1 ? ' manueller Wert' : ' manuelle Werte') + '.' : '')
      + ' Gibt es für denselben Zeitraum auch automatisch geladene Zahlen, entscheidet dein Manager oder deine Managerin, welcher Wert zählt.',
    inhalt: Number(Z.konten) > 0 || nm > 0 ? [{ typ: 'kennzahlen', eintraege: [{ label: 'Follower', wert: wert('follower') }, { label: 'Reichweite', wert: wert('reichweite') },
      { label: 'Aufrufe', wert: wert('aufrufe') }, { label: 'Interaktionen', wert: wert('interaktionen') }] }]
      : [{ typ: 'text', ton: 'grau', text: 'Noch keine verbundenen Accounts mit Zahlen.' }] });
}

// ---------- Meine Accounts: Verbinden, Erneuern, Trennen; i-Symbol je Verbindung; Zahlen per Screenshot ----------
if (D.accounts) {
  const karten = [];
  let verbunden = 0;
  for (const p of istA(D.accounts)) {
    const K = istA(p.konten);
    if (!K.length && !p.bereit) continue;
    const eintraege = [];
    for (const k of K) {
      if (k.status === 'verbunden') verbunden++;
      const laeuft = k.status === 'verbunden' && k.tage !== null && k.tage !== undefined && Number(k.tage) <= 14;
      const marke = k.status === 'abgelaufen' ? { text: 'abgelaufen', ton: 'warn' } : laeuft ? { text: Number(k.tage) === 0 ? 'läuft heute ab' : 'läuft in ' + k.tage + (Number(k.tage) === 1 ? ' Tag' : ' Tagen') + ' ab', ton: 'warn' } : { text: 'verbunden', ton: 'ok' };
      eintraege.push({ marke, text: s(k.text) + (k.weg_text ? ' (' + s(k.weg_text) + ')' : ''),
        aktion: { text: 'Trennen', aktion: 'tb_trennen', werte: { kanal_id: String(k.kanal_id) }, frage: s(p.name) + '-Account ' + s(k.text) + ' trennen? Neue Zahlen werden dann nicht mehr abgerufen.' } });
      if ((laeuft || k.status === 'abgelaufen') && p.bereit) eintraege.push({ text: 'Verbindung erneuern', aktion: { text: 'Erneuern', aktion: 'tb_verbinden', werte: { plattform: s(p.plattform) }, art: 'neben' } });
    }
    if (!K.length) eintraege.push({ text: 'Nicht verbunden', aktion: { text: 'Verbinden', aktion: 'tb_verbinden', werte: { plattform: s(p.plattform) }, art: 'neben' } });
    karten.push({ titel: s(p.name), info: istA(p.hinweise).map(s).filter(Boolean), eintraege, leer: '' });
  }
  const U = D.zahlen_upload && typeof D.zahlen_upload === 'object' ? D.zahlen_upload : null;
  const inhalt = [];
  if (karten.length) inhalt.push({ typ: 'karten', karten });
  else inhalt.push({ typ: 'text', ton: 'grau', text: 'Gerade lässt sich hier kein Account verbinden. Bitte bei deinem Manager oder deiner Managerin nachfragen.' });
  if (U) {
    inhalt.push({ typ: 'unterueberschrift', text: 'Zahlen hochladen',
      info: ['Für Zahlen ohne Verbindung, zum Beispiel die Statistik deines Instagram-Kanals: Bild (PNG, JPG, WEBP, bis 5 MB) oder PDF (bis 10 MB) hochladen. Die Zahlen werden ausgelesen und zählen, sobald dein Manager oder deine Managerin sie bestätigt hat.',
        // Migration 65: Info, was Zahlen per Screenshot liefern (talents_verbindung_info manuell / instagram_kanal, Texte in info_verbindung/texte.md)
        'Möglich sind Konto-Zahlen (Follower, Reichweite, Aufrufe, Interaktionen, Profilaufrufe, Anzahl Beiträge), Zahlen einzelner Beiträge und die Zielgruppe. Es zählt der Zeitraum auf dem Bild, keine Tageswerte.',
        'Instagram-Kanal nur per Bild: Mitglieder, Gesamtinteraktionen, Teilen, Umfrage-Stimmen. Diese Zahlen stehen getrennt vom Konto.'] });
    if (U.ki_bereit === false) inhalt.push({ typ: 'text', ton: 'grau', text: 'Hochladen ist gerade nicht möglich. Bitte später noch einmal versuchen.' });
    else inhalt.push({ typ: 'formular', id: 'zahlen', aktion: 'tb_zahlen', datei: true, felder: [{ typ: 'datei', name: 'datei', label: 'Bild oder PDF', accept: 'image/png,image/jpeg,image/webp,application/pdf', pflicht: true, breite: 'voll' }],
      knoepfe: [{ text: 'Hochladen' }] });
    if (Number(U.in_pruefung) > 0) inhalt.push({ typ: 'text', ton: 'grau', text: U.in_pruefung + (Number(U.in_pruefung) === 1 ? ' Datei wird' : ' Dateien werden') + ' gerade geprüft.' });
  }
  abschnitte.push({ id: 'accounts', titel: 'Meine Accounts', zahl: verbunden + ' verbunden', offen_standard: true,
    info: 'Du meldest dich direkt bei der Plattform an. Dein Passwort sieht niemand.', inhalt });
}

// ---------- Kampagnen (Briefing der Marke) ----------
if (D.kampagnen) {
  const KA = istA(D.kampagnen);
  const inhalt = [];
  for (const k of KA) {
    const paare = [['Zeitraum', k.zeitraum], ['Ziel', k.briefing_ziel], ['Kernbotschaft', k.kernbotschaft], ['Dos', k.dos], ["Don'ts", k.donts], ['Werbekennzeichnung', k.werbekennzeichnung],
      ['Hashtags', istA(k.hashtags).join(' ')], ['Accounts der Marke', istA(k.marken_konten).join(', ')]].filter(x => s(x[1]).trim() !== '').map(x => ({ label: x[0], wert: s(x[1]) }));
    inhalt.push({ typ: 'unterueberschrift', text: s(k.titel) }, { typ: 'paare', eintraege: paare });
  }
  if (!KA.length) inhalt.push({ typ: 'text', ton: 'grau', text: 'Gerade keine Kampagnen.' });
  abschnitte.push({ id: 'kampagnen', titel: 'Kampagnen', zahl: String(KA.length), offen_standard: false, inhalt });
}

// ---------- Dateien (Links der Kampagnen, geöffnet über die geprüfte Seite „link“) ----------
if (D.dateien) {
  const DA = istA(D.dateien);
  abschnitte.push({ id: 'dateien', titel: 'Dateien', zahl: String(DA.length), offen_standard: false,
    inhalt: [{ typ: 'liste', leer: 'Keine Dateien.', eintraege: DA.map(d => ({ fett: s(d.titel), text: s(d.kampagne), neben: s(d.dienst_text), ziel: link('kl', d.id), ziel_text: 'Öffnen' })) }] });
}
if (!abschnitte.length) abschnitte.push({ id: 'leer', titel: 'Dein Bereich', offen_standard: true, inhalt: [{ typ: 'text', ton: 'grau', text: 'Hier ist gerade nichts mit dir geteilt.' }] });
// ---------- Deine Ordner (Migration 67): für dich freigegebene Ordner im Speicherort; Dateien lädt Ally für dich herunter ----------
if (OT.ok === true && OT.darf === true && istA(OT.ordner).length) {
  const OO = istA(OT.ordner);
  const akt = OO.find(o => s(o.id) === s(OPZ.id));
  const inhalt = [];
  const groesse = b => b === null || b === undefined ? '' : b < 1024 ? b + ' B' : b < 1048576 ? (Math.round(b / 102.4) / 10).toLocaleString('de-DE') + ' KB'
    : (Math.round(b / 104857.6) / 10).toLocaleString('de-DE') + ' MB';
  if (OT.bereit !== true) inhalt.push({ typ: 'text', ton: 'grau', text: 'Die Ordner sind gerade nicht erreichbar. Bitte später noch einmal versuchen.' });
  if (!akt) inhalt.push({ typ: 'liste', leer: 'Keine Ordner.', eintraege: OO.map(o => ({ fett: s(o.name), text: o.seit ? 'geteilt am ' + s(o.seit) : '',
    ziel: { seite: 'talent-bereich', parameter: { to: s(o.id) }, anker: 'a-ordner' }, ziel_text: 'Öffnen' })) });
  else {
    const sub = s(OPZ.pfad), teile = sub ? sub.split('/') : [];
    const zu = p => ({ seite: 'talent-bereich', parameter: Object.assign({ to: s(akt.id) }, p ? { tp: p } : {}), anker: 'a-ordner' });
    inhalt.push({ typ: 'unterueberschrift', text: [s(akt.name)].concat(teile).join(' › ') });
    inhalt.push({ typ: 'aktion', text: teile.length ? 'Eine Ebene höher' : 'Alle Ordner', ziel: teile.length ? zu(teile.slice(0, -1).join('/')) : { seite: 'talent-bereich', anker: 'a-ordner' } });
    if (!OL || OL.ok !== true) inhalt.push({ typ: 'text', ton: 'warn', text: s((OL && OL.fehler) || 'Der Ordner konnte gerade nicht gelesen werden. Bitte später noch einmal versuchen.') });
    else {
      const max = (Number(OT.max_mb) || 0) * 1048576;
      if (OL.gekuerzt) inhalt.push({ typ: 'text', ton: 'grau', text: 'Es werden nur die ersten ' + istA(OL.eintraege).length + ' von ' + OL.anzahl + ' Einträgen gezeigt.' });
      inhalt.push({ typ: 'tabelle', id: 'ordner-inhalt', titel: 'Inhalt von ' + s(akt.name), leer: 'Dieser Ordner ist leer.', je_seite: 500,
        spalten: [{ schluessel: 'name', titel: 'Name' }, { schluessel: 'groesse', titel: 'Größe', ausrichtung: 'rechts' }, { schluessel: 'laden', titel: 'Datei' }],
        zeilen: istA(OL.eintraege).map(e => { const p = (sub ? sub + '/' : '') + s(e.name); const kurz = p.length <= 200; const gross = !e.ordner && max > 0 && Number(e.bytes) > max;
          return { zellen: { name: e.ordner && kurz ? { text: s(e.name), ziel: zu(p) } : { text: s(e.name) }, groesse: e.ordner ? 'Ordner' : groesse(e.bytes),
            laden: e.ordner ? '' : gross ? 'zu groß zum Herunterladen' : !kurz ? 'Name zu lang' : { text: 'Herunterladen', ziel: { seite: 'datei', parameter: { o: s(akt.id), d: p } } } } }; }) });
    }
  }
  abschnitte.push({ id: 'ordner', titel: 'Deine Ordner', zahl: String(OO.length), offen_standard: !!akt, info: 'Ordner, die mit dir geteilt sind. Dateien lädt Ally für dich herunter.', inhalt });
}
// Migration 196 (Plan 62, Stefan 01.11.2026: „Das Talent darf sein Mediakit selbst pflegen“): „Mein Mediakit“ – hochladen bzw. ersetzen und Link zum Teilen
