      { typ: 'aktion', text: 'Link widerrufen', aktion: 'mk_link_weg', werte: {}, frage: 'Link widerrufen? Wer ihn hat, sieht das Mediakit dann nicht mehr.' });
    else if (da && MK.adresse === true) inhalt.push({ typ: 'aktion', text: 'Link zum Teilen erstellen', aktion: 'mk_link', werte: {} });
