      felder: [{ typ: 'datei', name: 'datei', label: 'Mediakit (PDF)', accept: 'application/pdf', pflicht: true, breite: 'voll' }], knoepfe: [{ text: da ? 'Ersetzen' : 'Hochladen' }] });
    abschnitte.push({ id: 'mediakit', titel: 'Mein Mediakit', zahl: da ? st(MK.datei.stand) : '', offen_standard: true,
